WITH gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY country ORDER BY started_at ASC, id ASC) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY country ORDER BY started_at ASC, id ASC) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS is_new_session FROM sessions), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY country ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT CASE WHEN burst_id >= 7 THEN 'LARGE' ELSE 'SMALL' END AS burst_id_tier, DATE_TRUNC('WEEK', started_at) AS week_start, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS duration_min, APPROX_PERCENTILE(burst_id, 0.95) AS burst_id_p95, AVG(is_new_session) FILTER (WHERE country = 'TH') AS th_avg_is_new_session, ROUND(SUM(is_new_session) / NULLIF(COUNT(CASE WHEN country = 'SG' THEN 1 END), 0), 2) AS is_new_session_per_sg FROM sessionized GROUP BY CASE WHEN burst_id >= 7 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('WEEK', started_at) ORDER BY th_avg_is_new_session ASC;
